<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Booking Kamar · Kos XYZ</title></head><body><main><h1>Booking Kamar</h1><p>Isi data. Admin akan memproses booking Anda.</p><?php if($errors->any()): ?><div class="error"><?php echo e($errors->first()); ?></div><?php endif; ?><form method="POST" action="<?php echo e(route('booking.store')); ?>"><?php echo csrf_field(); ?><label>Kamar<select name="kamar_id" required><?php $__currentLoopData = $kamars; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $kamar): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($kamar->id); ?>" <?php if($selectedKamar === $kamar->id): echo 'selected'; endif; ?>><?php echo e($kamar->nama); ?> - Rp <?php echo e(number_format($kamar->harga,0,',','.')); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Nama lengkap<input name="nama_lengkap" required value="<?php echo e(old('nama_lengkap')); ?>"></label><label>No. WhatsApp<input name="no_hp" required value="<?php echo e(old('no_hp')); ?>" placeholder="08123456789"></label><label>Email<input type="email" name="email" value="<?php echo e(old('email')); ?>"></label><label>Tanggal masuk<input type="date" name="tanggal_masuk" required min="<?php echo e(now()->format('Y-m-d')); ?>" value="<?php echo e(old('tanggal_masuk')); ?>"></label><label>Durasi sewa (bulan)<input type="number" name="durasi_bulan" min="1" max="24" required value="<?php echo e(old('durasi_bulan',1)); ?>"></label><label>Catatan<textarea name="catatan"><?php echo e(old('catatan')); ?></textarea></label><button type="submit">Kirim Booking</button></form></main><style>body{font-family:Arial;background:#f1f5f9;padding:20px}main{max-width:700px;margin:30px auto;background:#fff;padding:28px;border-radius:16px}label{display:block;margin:14px 0;font-weight:600}input,select,textarea{display:block;width:100%;padding:10px;margin-top:5px;box-sizing:border-box}textarea{min-height:90px}button{padding:11px 20px;background:#b45309;color:white;border:0;border-radius:9px}.error{color:#b91c1c}</style></body></html>
